function initOsceMenu() {
  const files = Array.isArray(globalThis.agoraSourceFiles) ? globalThis.agoraSourceFiles.filter(file => /\.md$/i.test(file)) : [];
  const el = id => document.getElementById(id);
  const label = value => value.replace(/\.md$/i, '').replace(/[-_]/g, ' ');
  const references = Array.isArray(globalThis.agoraReferences) ? globalThis.agoraReferences : [];
  const topic = file => ({file, title: references.find(value => value.path === file)?.label || label(file.split('/').at(-1))});
  let selected = null, location = [], current = files.map(topic);
  function choose(value) {
    selected = value; el('selection').textContent = value.title; el('start').disabled = false;
    document.querySelectorAll('.condition').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.source === value.file)));
  }
  function browse(parts = []) {
    location = parts;
    const prefix = parts.length ? parts.join('/') + '/' : '';
    current = files.filter(file => file.startsWith(prefix)).map(topic);
    const folders = [...new Set(current.map(value => value.file.slice(prefix.length)).filter(value => value.includes('/')).map(value => value.split('/')[0]))];
    const topics = current.filter(value => !value.file.slice(prefix.length).includes('/'));
    el('categories').hidden = parts.length > 0; el('condition-page').hidden = parts.length === 0;
    el('specialty-title').textContent = parts.map(label).join(' / ');
    const container = parts.length ? el('topics') : el('categories'); container.replaceChildren();
    if (!parts.length && folders.length && !topics.length) {
      for (const folder of folders) {
        const matches = current.filter(value => value.file.startsWith(folder + '/'));
        const specialties = [...new Set(matches.filter(value => value.file.split('/').length > 2).map(value => value.file.split('/')[1]))];
        const heading = document.createElement('h2'); heading.textContent = label(folder);
        const grid = document.createElement('div'); grid.className = 'specialties';
        if (specialties.length && !matches.some(value => value.file.split('/').length === 2)) {
          for (const specialty of specialties) {
            const button = document.createElement('button');
            button.append(document.createTextNode(label(specialty)));
            const count = document.createElement('small');
            count.textContent = matches.filter(value => value.file.startsWith(folder + '/' + specialty + '/')).length;
            button.append(count); button.setAttribute('aria-label', label(specialty) + ' (' + label(folder) + ')');
            button.onclick = () => browse([folder, specialty]); grid.append(button);
          }
        } else {
          const button = document.createElement('button'); button.textContent = label(folder);
          button.onclick = () => browse([folder]); grid.append(button);
        }
        container.append(heading, grid);
      }
      return;
    }
    const grid = document.createElement('div'); grid.className = 'specialties';
    const target = parts.length ? container : grid;
    for (const folder of folders) {
      const button = document.createElement('button'); button.textContent = label(folder);
      button.onclick = () => browse([...parts, folder]); target.append(button);
    }
    for (const value of topics) {
      const button = document.createElement('button'); button.className = 'condition';
      button.textContent = value.title; button.dataset.source = value.file;
      button.setAttribute('aria-pressed', String(selected?.file === value.file));
      button.onclick = () => choose(value); target.append(button);
    }
    if (!parts.length) container.append(grid);
  }
  browse();
  if (!files.length) el('status').textContent = 'No Markdown references loaded. Choose a reference folder in template settings.';
  el('back').onclick = () => browse(location.length > 2 ? location.slice(0, -1) : []);
  el('count').oninput = () => {el('count-value').textContent = el('count').value;};
  el('random').disabled = !files.length;
  el('random').onclick = () => {
    if (!current.length) return;
    const value = current[Math.floor(Math.random() * current.length)];
    browse(value.file.split('/').slice(0, -1)); choose(value);
  };
  el('start').onclick = async () => {
    if (!selected || el('start').disabled) return;
    const questions = Number(el('count').value);
    if (!Number.isInteger(questions) || questions < 1 || questions > 40) return;
    const parts = selected.file.split('/').slice(0, -1);
    const input = JSON.stringify({...(parts.length > 1 ? {subject: parts[0]} : {}), specialty: parts.at(-1) || 'References', condition: selected.title, questions});
    el('start').disabled = true;
    try {
      const sent = await Websandbox.connection.remote.sendPrompt({text: input, sourceFiles: [selected.file]});
      el('status').textContent = sent === false ? 'Not sent. Try again.' : 'Submitted · continue in chat';
      if (sent === false) el('start').disabled = false;
    } catch (_) {el('status').textContent = 'Not sent. Try again.'; el('start').disabled = false;}
  };
}
